<section class="page-head"><div><p class="muted">Configura qué puede hacer cada rol y hasta dónde puede ver.</p></div><button class="btn btn-primary" id="newRoleBtn">+ Rol personalizado</button></section><div id="roleGrid" class="role-grid"></div>
<div class="modal hidden" id="roleModal"><div class="modal-card modal-wide"><div class="modal-head"><div><span class="eyebrow">CONTROL DE ACCESO</span><h2 id="roleModalTitle">Nuevo rol</h2></div><button class="icon-btn" data-close-modal>✕</button></div><form id="roleForm" class="form-grid"><input type="hidden" name="rol_id"><label>Código<input name="codigo" required></label><label>Nombre<input name="nombre" required></label><label class="full">Descripción<textarea name="descripcion" rows="2"></textarea></label><label>Alcance<select name="alcance"><option value="GLOBAL">Global</option><option value="DEPARTAMENTO">Departamento</option><option value="JERARQUIA">Jerarquía</option><option value="PROPIO">Propio</option></select></label><label>Estatus<select name="estatus"><option>ACTIVO</option><option>INACTIVO</option></select></label><div class="full"><div class="section-label">Permisos</div><div id="permissionGrid" class="permission-grid"></div></div><div class="form-actions full"><button type="button" class="btn btn-ghost" data-close-modal>Cancelar</button><button class="btn btn-primary" type="submit">Guardar rol</button></div></form></div></div>
